package com.siansiansu.taigikeyboard.ime.text.layout

import androidx.annotation.DrawableRes
import com.siansiansu.taigikeyboard.R
import com.siansiansu.taigikeyboard.i18n.generated.StringKey

// The keyboard layouts offered by the Layout tab and the in-keyboard layout picker, with the card
// screenshot each shows (regenerated by PreviewAssetGeneratorTest). Mirrors iOS
// KeyboardLayoutType.previewImageName.

data class KeyboardLayoutOption(
    val key: String,
    val labelKey: StringKey,
    @param:DrawableRes val previewRes: Int,
)

object KeyboardLayoutOptions {
    // Section 1 — romanization keyboards (matches iOS LayoutTab / LayoutSelectionOverlay).
    val romanization =
        listOf(
            KeyboardLayoutOption("phahTaigi", StringKey.LAYOUT_PHAH_TAIGI_LAYOUT, R.drawable.layout_phahtaigi_preview),
            KeyboardLayoutOption("qwerty", StringKey.LAYOUT_STANDARD_LAYOUT, R.drawable.layout_standard_preview),
            KeyboardLayoutOption("moe1", StringKey.LAYOUT_MOE1_LAYOUT, R.drawable.layout_moe1_preview),
            KeyboardLayoutOption("moe2", StringKey.LAYOUT_MOE2_LAYOUT, R.drawable.layout_moe2_preview),
        )

    // Section 2 — Taigi phonetic keyboards.
    val phonetic =
        listOf(
            KeyboardLayoutOption("tps", StringKey.LAYOUT_TPS_LAYOUT, R.drawable.layout_tps_preview),
        )
}
